// Shared inputs for the ET0 editorial title fixtures
// (docs/editorial-typography-improvement-plan.md#et0--tracked-fixtures-and-baseline).
//
// Every fixture uses tracked, license-free inputs only: the synthetic clip in
// media/ (generated by scripts/editorial-titles/generate-fixture-clip.ts) and
// the repository's pinned OFL fonts. Fixtures reproduce engine findings as they
// behave today; they are expected-failure baselines, not good designs.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { video } from "@still-shift/motion";
import { fontAsset } from "@still-shift/motion/node";

const here = import.meta.url;
const descriptor = JSON.parse(
  readFileSync(
    fileURLToPath(new URL("./media/editorial-bands.descriptor.json", here)),
    "utf8",
  ),
) as {
  asset: {
    id: string;
    path: string;
    sha256: `sha256:${string}`;
    width: number;
    height: number;
    frameCount: number;
    frameRate: { numerator: number; denominator: number };
    color: {
      primaries: "bt709";
      transfer: "bt709";
      matrix: "bt709";
      range: "tv";
    };
  };
};

export const clipAsset = {
  ...descriptor.asset,
  type: "video" as const,
  path: fileURLToPath(new URL(`./media/${descriptor.asset.path}`, here)),
};

/** 1080×1920 at 24 fps for 4 s, matching the synthetic clip. */
export const frame = { width: 1080, height: 1920, fps: 24, frames: 96 };

/** Plain paper background for fixtures whose measurement must not see video. */
export const paper = "#F4EFE2";

/** Title timing: entrance, hold, exit and out point (frames). */
export const beats = { enter: 4, held: 24, exit: 66, gone: 84 };

/** The synthetic clip at full frame, untransformed. */
export function clip() {
  return video("clip", clipAsset, {
    size: [frame.width, frame.height],
    fit: "stretch",
  });
}

const font = (
  id: string,
  rel: string,
  options: Parameters<typeof fontAsset>[2],
) => fontAsset(id, rel, { relativeTo: here, ...options });

export const fonts = {
  serif: await font(
    "serif",
    "../../../assets/story-motion/fonts/source-serif-4-semibold.otf",
    { weight: "600" },
  ),
  sans: await font(
    "sans",
    "../../../assets/story-motion/fonts/plex-sans-semibold.ttf",
    { weight: "600" },
  ),
  mono: await font(
    "mono",
    "../../../assets/story-motion/fonts/plex-mono-medium.ttf",
    { weight: "500" },
  ),
  thai: await font(
    "thai",
    "../../../assets/ecommerce-motion/fonts/noto-sans-thai.ttf",
    {
      weight: "400",
      variable: {
        wght: { min: 100, default: 400, max: 900 },
        wdth: { min: 62.5, default: 100, max: 100 },
      },
    },
  ),
};

/** Exact copy, shared with the 2026-11-15 proof. */
export const copy = {
  kicker: "THREE WAYS TO WEAR",
  headline: "Olive",
  issue: "No. 03 — Courtyard Edit",
  thaiHeadline: "สามลุค",
  thaiCluster: "ลุค",
  mixedLabel: "3 ลุค · OLIVE GREEN",
  minimal: "three ways to wear olive",
  minimalCredit: "COURTYARD EDIT · 03",
} as const;
